import { addDays, generateIcsCalendar, type CalendarTask } from "../core";
import type { CalendarOptions } from "./ExportPlan";

/**
 * How a timed task comes out under the current time settings, as the lines a calendar app reads.
 *
 * "Local wall time" versus "Fixed time zone" is the one setting whose effect nobody can picture
 * from its description. Showing the actual DTSTART it produces — floating, or with a TZID — makes
 * the difference concrete, and it is generated by the real exporter, so it cannot be wrong.
 */
export function sampleEventLines(options: CalendarOptions, today: string, now: Date): string[] {
  const task: CalendarTask = {
    title: "Team sync",
    sourcePath: "Sample.md",
    line: 1,
    date: addDays(today, 1),
    startTime: "09:00",
    tags: [],
    status: "todo",
    stableId: "sample",
  };
  const { ics } = generateIcsCalendar(
    [task],
    {
      calendarName: options.calendarName,
      productId: "-//Task Calendar Bridge//EN",
      defaultDurationMinutes: options.defaultDurationMinutes,
      timeMode: options.timeMode,
      timeZone: options.timeZone,
      allDayReminderTime: options.allDayReminderTime,
      vaultName: "",
      exportTags: false,
      linkToSource: false,
    },
    now
  );
  // Only the event's own lines: a VTIMEZONE carries DTSTART lines of its own.
  const lines = ics.split("\r\n");
  return lines.slice(lines.indexOf("BEGIN:VEVENT")).filter((line) => /^(DTSTART|DTEND|DURATION)[;:]/.test(line));
}
